function Runner(waits, options) {
  this._waits = waits;
  this._options = options || {};
  this._count = 0;
}
module.exports = Runner;

Runner.prototype.next = function () {
  var wait = this._waits.shift();
  if (wait === undefined) {
    return -1;
  }
  this._count++;
  return wait;
};

Runner.prototype.count = function () {
  return this._count;
};
